/**
 * The CMS tab and app icons (staff octagon with the lantern), generated by AlUmmahNow
 * packages/app-icons into app-icons.generated.ts. Served from code: this Worker has no static assets.
 */
import { Hono } from "hono";
import { APP_ICONS } from "./app-icons.generated.ts";

/** Fixed names, so not immutable: a day fresh, then a week stale-while-revalidate. */
const CACHE = "public, max-age=86400, stale-while-revalidate=604800";

const bodies = new Map(Object.entries(APP_ICONS).map(([path, f]) => [path, { type: f.type, body: Uint8Array.from(atob(f.body), (ch) => ch.charCodeAt(0)) }]));

/** Request paths the icons are served at (public, before the session and config checks). */
export const ICON_PATHS = [...bodies.keys()];

export function iconResponse(path: string): Response | undefined {
   const f = bodies.get(path);
   if (!f) return undefined;
   return new Response(f.body, { headers: { "content-type": f.type, "cache-control": CACHE, "x-content-type-options": "nosniff" } });
}

export function appIconRoutes(): Hono {
   const app = new Hono();
   for (const path of ICON_PATHS) app.get(path, () => iconResponse(path)!);
   return app;
}

/** QA and local get a violet corner dot, stage a pink one: one build serves stage and production. */
export function faviconSvgPath(environment: string | undefined): string {
   if (environment === "production") return "/favicon.svg";
   if (environment === "stage") return "/favicon-stage.svg";
   return "/favicon-qa.svg";
}

/** The staff octagon's ink, for theme-color and the manifest. */
export const ICON_THEME_COLOR = "#09151e";
